package hugolib

import (
	"testing"

	qt "github.com/frankban/quicktest"
)

func TestZZDebug(t *testing.T) {
	t.Parallel()

	files := `
-- hugo.toml --
disableKinds = ['rss','section','sitemap','taxonomy','term']
-- layouts/index.html --
Test D: {{ (site.GetPage "p2").Title }}
-- layouts/_default/single.html --
{{ .Title }}
-- content/s2/_content.gotmpl --
{{ .AddPage (dict "path" "p2" "title" "p2") }}
`

	b := Test(t, files)
	s := b.H.Sites[0]
	m := s.pageMap
	var keys []string
	m.treePages.WalkPrefixRaw("", func(key string, v contentNodeI) bool {
		keys = append(keys, key)
		if ps, ok := v.(*pageState); ok {
			t.Logf("tree key=%q kind=%q hasfile=%v pathinfo=%q basename=%q", key, ps.Kind(), ps.File() != nil, ps.PathInfo().Path(), ps.PathInfo().BaseNameNoIdentifier())
		}
		return false
	})
	n1 := m.pageReverseIndex.Get("p2")
	t.Logf("reverse index p2: %v", n1)
	pf := newPageFinder(m)
	pp, err := pf.getPage(nil, "/p2")
	t.Logf("getPage /p2: %v %v", pp, err)
	b.Assert(pp, qt.IsNotNil)
}

