Handle: func(s string, n contentNodeI, match doctree.DimensionFlag) (bool, error) {
	p := n.(*pageState)
	var key string
	if p.File() != nil {
		fpi := p.File().FileInfo().Meta().PathInfo
		if fpi != nil && !fpi.IsContentData() {
			key = fpi.BaseNameNoIdentifier()
		}
	}
	if key == "" {
		// Page not backed by a regular content file, e.g. created
		// by a content adapter.
		switch p.Kind() {
		case kinds.KindPage, kinds.KindSection:
			if pi := p.PathInfo(); pi != nil {
				key = pi.BaseNameNoIdentifier()
			}
		}
	}
	if key != "" {
		add(key, p)
	}
	return false, nil
},

